"""Evidence-backed paper versus final restart audit, no test-driven changes."""
import sys,json,html,collections,re,hashlib
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];sys.path.insert(0,str(ROOT));sys.path.insert(0,str(HERE))
import numpy as np
from audit import group
OUT=HERE/'results';s=json.loads((OUT/'summary.json').read_text());receipt=json.loads((OUT/'independent_verification.json').read_text());live=json.loads((OUT/'full_pipeline_audit.json').read_text());assert live['verified']
names=list(s['selected_epochs']);split=json.loads((HERE/'split.json').read_text())
for r in receipt['models']:
    assert hashlib.sha256((OUT/f'{r["model"]}_best.pt').read_bytes()).hexdigest()==r['checkpoint_sha256']
paper={
'alexnet':dict(accuracy=.9286,precision=.9021,sensitivity=.9897,auc=.9783,epochs=200),
'densenet121':dict(accuracy=.9262,precision=.9118,sensitivity=.9923,auc=.9878,epochs=100),
'googlenet':dict(accuracy=.9312,precision=.9044,sensitivity=.9948,auc=.9829,epochs=50),
'inception_v3':dict(accuracy=.9201,precision=.9030,sensitivity=.9846,auc=.9733,epochs=100),
'resnet18':dict(accuracy=.9423,precision=.9158,sensitivity=.9948,auc=.9936,epochs=200),
'ensemble':dict(accuracy=.9639,precision=.9328,sensitivity=.9962,auc=.9934)}
models={r['model']:r['test_metrics'] for r in receipt['models']};models['ensemble']=s['metrics']
comparisons={n:{k:dict(paper=paper[n].get(k),local=m.get(k),difference_percentage_points=100*(m[k]-paper[n][k]) if k in paper[n] else None) for k in ['accuracy','precision','sensitivity','specificity','pneumonia_f1','normal_f1','macro_f1','balanced_accuracy','auc']} for n,m in models.items()}
normal_prefix={}
for part,rows,suffix in [('validation',[split['records'][i] for i in split['validation_indices']],'validation'),('test',split['test_records'],'test')]:
    p=np.stack([np.load(OUT/f'{n}_{suffix}_probabilities.npy') for n in names]);pred=((p>=.5).sum(0)>=3).astype(int)
    normal_prefix[part]={}
    for prefix in ['IM','NORMAL2']:
        ix=[i for i,r in enumerate(rows) if r['label']==0 and ('NORMAL2' if 'NORMAL2' in r['source_path'] else 'IM')==prefix]
        normal_prefix[part][prefix]=dict(n=len(ix),false_positives=int(pred[ix].sum()),false_positive_rate=float(pred[ix].mean()))
tp=390*.9962;fp=tp*(1/.9328-1)
result=dict(comparison=comparisons,source='P7 Table2, printed PDF page13: https://eprints.qut.edu.au/199742/1/applsci_10_00559_1_.pdf',fresh_full_test_forward_verified=True,selected_epochs=s['selected_epochs'],normal_prefix_diagnostics=normal_prefix,view_diagnostics=live['view_diagnostics'],filename_group_proxy_intersections=live['filename_group_proxy_intersections'],proxy_warning=live['proxy_warning'],paper_conditional_consistency=dict(assumption='One binary confusion matrix on390 pneumonia and234 normal test records',reported_accuracy=.9639,accuracy_implied_by_reported_positive_precision_recall=(tp+234-fp)/624,implied_tp=tp,implied_fp=fp,warning='Averaging, different definitions/partition or reporting errors could explain this. It is not proof of fabrication.'),confirmed_protocol_departures=['4164 training images versus5232 in the paper','15 local epochs versus50-200 paper epochs','Four fixed cached views, one view for an entire epoch','Frozen early BatchNorm running statistics and unspecified late normalization details','Validation-selected checkpoints rather than verified author selection','Assumed transform/noise/batch/normalization settings'],causal_conclusion='No arithmetic, test-order or stale-cache error found in audited inference. The learning/evaluation protocol differs materially and normal-class generalization is poor. The exact causal contribution of each departure is not established.',training_or_thresholds_changed=False)
result['saved_checkpoints_unchanged_since_verification']=True
result['metadata_issue']='summary.validation.test_evaluated remains false because the pre-test validation report was embedded without updating that flag. This is misleading metadata, not the absence of a test evaluation. Per-image CSV, saved scores and fresh full-test audit establish that test evaluation ran.'
(OUT/'post_run_audit.json').write_text(json.dumps(result,indent=2))
def pct(x):return 'Not reported' if x is None else f'{100*x:.2f}%'
rows=''.join(f'<tr><th>{k.replace("_"," ")}</th><td>{pct(v["paper"])}</td><td>{pct(v["local"])}</td><td>'+('—' if v['difference_percentage_points'] is None else f'{v["difference_percentage_points"]:+.2f} pp')+'</td></tr>' for k,v in comparisons['ensemble'].items())
modelrows=''.join('<tr><th>'+n+'</th>'+''.join('<td>'+pct(paper[n][k])+' / '+pct(models[n][k])+'</td>' for k in ['accuracy','precision','sensitivity','auc'])+'</tr>' for n in names)
body='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Final reproduction gap audit</title><style>body{font:17px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#20222b;background:#faf9f6;max-width:1060px;margin:55px auto;padding:0 25px}h1{font-size:38px;line-height:1.2}h2{margin-top:38px;font-size:25px}table{border-collapse:collapse;width:100%;background:white;font-size:15px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:right}th:first-child{text-align:left}thead{background:#eee9fb}a{color:#5841ab}.muted{color:#676773}</style>
<h1>Final reproduction gap audit</h1><p>The final15-epoch experiment obtained85.74% accuracy and81.55% precision on624 test records. Fresh forwards through all five models reproduced the saved predictions with no changed class decisions. This is a genuine negative result of our declared reconstruction, not evidence of cheating.</p>
<h2>Final ensemble versus the published ensemble</h2><table><thead><tr><th>Metric</th><th>Paper reported</th><th>Audited restart</th><th>Difference</th></tr></thead><tbody>'''+rows+'''</tbody></table><p>Paper values come from Table2. Unreported specificity/F1 scores cannot be reliably reconstructed from its inconsistent headline metrics. Our AUC uses mean pneumonia probabilities; the authors do not supply an executable ROC-score definition.</p>
<h2>Each model</h2><table><thead><tr><th>Model</th><th>Accuracy paper / ours</th><th>Precision paper / ours</th><th>Recall paper / ours</th><th>AUC paper / ours</th></tr></thead><tbody>'''+modelrows+'''</tbody></table>
<h2>What fails on our test set</h2><p>True normal:146 correct,88 false pneumonia predictions. True pneumonia:389 correct,1 missed. Validation has6 false positives among270 normals, versus88 among234 test normals. Normal recall drops from97.78% validation to62.39% test. Fifty-four normal test images receive pneumonia votes from every component, demonstrating shared errors. Class prevalence alone cannot explain this conditional normal-class error-rate change.</p>
<p>Filename-prefix screening also shows the error increase within both normal-image categories: IM validation3/122 false positives versus test16/69; NORMAL2 validation3/148 versus test72/165. These are descriptive filename groups, not verified hospital/acquisition subgroups. They support a real validation/test generalization discrepancy without establishing its cause.</p>
<h2>Our important implementation departures</h2><p>We trained on4164 images, about20.4% fewer than the paper's5232, after reserving1042 group-validation records and removing duplicates. Fifteen epochs is shorter than its50-200 schedules. Each local epoch uses one entire fixed view, cycling clean/aug1/aug2/aug3, rather than ordinary freshly sampled or batch-mixed augmentation. This was a resource-driven approximation.</p>
<p>Every selected checkpoint followed a clean epoch: ResNet13, DenseNet9, GoogLeNet5, Inception13, AlexNet1. Augmented-view epochs consistently show lower validation macro F1. GoogLeNet averages0.9753 after clean epochs versus approximately0.9291-0.9366 after augmented epochs. This is a concrete instability signal. Changing augmentation distribution and BatchNorm statistics may contribute, but epoch and learning-rate effects are confounded and the logs alone do not prove a mechanism. AlexNet has no BatchNorm, so BatchNorm cannot explain the entire pattern.</p>
<p>Frozen-prefix caching also freezes early BatchNorm statistics. Exact author normalization, noise, augmentation parameters, batch size, checkpoint policy and classifier details are not fully verified. CPU hardware itself does not explain the gap, but resource-driven changes to training can. We should not have portrayed these modifications as removing every reproduction difference.</p>
<h2>Checks that passed</h2><p>Class counts and image order match the original manifest. Source hashes do not overlap non-test/test. Fresh image forwards on every test record match the saved feature caches and final probabilities. Recomputed vote labels and confusion counts agree. Saved checkpoints match validation-selected epochs. Earlier full-network versus split-prefix/tail architecture checks gave zero forward difference. No test thresholds or checkpoints were tuned to improve this audit.</p>
<p>Filename person-number proxies overlap across official non-test/test:134 train/test and36 validation/test groups. These are pneumonia numbers, mostly across bacterial/viral filenames, and may be reused counters rather than the same patients. They do not prove leakage. Patient-independent test evaluation has not been certified. Exact-hash checks cannot establish it.</p><p>A metadata issue exists: the embedded validation report still says test_evaluated=false because it was written before final testing. Test evaluation did run, as shown by624 per-image outputs and the fresh-forward audit. The stale flag does not affect predictions or scores.</p>
<h2>Issues in the published target</h2><p>If99.62% recall and93.28% positive-class precision describe one confusion matrix on390 pneumonia and234 normal images, they imply approximately95.28% accuracy, not96.39%. Neither96.39% accuracy on624 records nor99.62% recall on390 positives corresponds to a single integer-count result rounded to two decimals. Run averages, another evaluation partition, metric definitions or reporting errors could explain this; repeated-run averaging is not documented sufficiently to resolve it. Figure12 also appears to label a conventional ROC horizontal axis as specificity. None of these observations establishes fabrication.</p>
<h2>Conclusion and next controlled checks</h2><p>The score gap is real. No audited inference or metric-calculation bug explains it. Our truncated training and caching/validation protocol are not an exact reproduction. Poor normal-case generalization and systematic augmentation-view effects are the strongest local findings; causal contributions remain unresolved.</p><p>Before expanding the model, isolate augmentation mixing and normalization policy with a fixed split, initialization and budget. Select using validation and inspect that curve, without chasing test numbers. Do not launch another bundled multi-change run or select an epoch/threshold from test performance. Crop plus ViT remains an untested hypothesis and cannot be promised to repair this gap.</p>
<p><a href="https://eprints.qut.edu.au/199742/1/applsci_10_00559_1_.pdf">Full base paper</a> · <a href="full_pipeline_audit.json">Fresh-forward audit receipt</a> · <a href="post_run_audit.json">Detailed comparison data</a></p></html>'''
body=re.sub(r'\b(final|on|among|versus|from|to|of|its|was|Our|our|the|Table|Figure|using|with|has|and|a|at|normal|training|epochs|recall|approximately|accuracy|precision|ResNet|DenseNet|GoogLeNet|Inception|AlexNet)(?=\d)',r'\1 ',body)
(OUT/'FINAL_REPRODUCTION_AUDIT.html').write_text(body);print(json.dumps(result,indent=2))
